// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy, Bank} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(uint256 seed) public {
        Bank bank = new Bank{salt: bytes32(seed)}();
        vm.prank(address(bank));
        bool ok;
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && c.tokenBalance(address(bank)) == 20, "airDrop from valid Bank must credit 20 tokens");
    }
}
